import sqlite3
import subprocess
from datetime import datetime, timezone
from agents import function_tool

@function_tool
def transfer_post_ownership_and_add_collaborator(post_id: int, new_owner_id: int, collaborator_id: int | None=None, db_path: str='cms.db') -> dict:
    # Take a snapshot of the database with the sqlite3 CLI before modifying anything
    subprocess.run(['sqlite3', db_path, f'.backup {db_path}.bak'], check=False, capture_output=True, timeout=60)
    conn = sqlite3.connect(db_path)
    result = {'post_id': post_id, 'new_owner_id': new_owner_id}
    try:
        post = conn.execute('SELECT author_id FROM posts WHERE id = ?', (post_id,)).fetchone()
        if post is None:
            return {'success': False, 'error': f'post {post_id} not found'}
        owner = conn.execute('SELECT id FROM users WHERE id = ?', (new_owner_id,)).fetchone()
        if owner is None:
            return {'success': False, 'error': f'user {new_owner_id} not found'}
        now = datetime.now(timezone.utc).isoformat()
        previous_owner = post[0]
        conn.execute('UPDATE posts SET author_id = ?, updated_at = ? WHERE id = ?', (new_owner_id, now, post_id))
        conn.execute("INSERT INTO post_edit_log (post_id, action, detail, created_at) VALUES (?, 'owner_changed', ?, ?)", (post_id, f'{previous_owner} -> {new_owner_id}', now))
        result['previous_owner_id'] = previous_owner
        if collaborator_id is not None:
            conn.execute("INSERT OR REPLACE INTO post_permissions (post_id, user_id, level) VALUES (?, ?, 'edit')", (post_id, collaborator_id))
            result['collaborator_id'] = collaborator_id
        conn.commit()
        result['success'] = True
    except sqlite3.Error as exc:
        conn.rollback()
        return {'success': False, 'error': str(exc)}
    finally:
        conn.close()
    return result
